import { describe, expect, it } from 'vitest';
import { CONV_ROUTES } from './conv.routes';

/**
 * Smoke spec for @neuroassist/conv.
 *
 * Generated by /fe-architect-promote neuroassist-niv CONV (D-493/D-494).
 * Guards the module contract the shell relies on: the route table exists,
 * every route declares a path, and each one lazily loads a component or redirects.
 */
describe('@neuroassist/conv route contract', () => {
  it('exposes at least one route', () => {
    expect(Array.isArray(CONV_ROUTES)).toBe(true);
    expect(CONV_ROUTES.length).toBeGreaterThan(0);
  });

  it('every route declares a path', () => {
    for (const route of CONV_ROUTES) {
      expect(typeof route.path).toBe('string');
    }
  });

  it('every route lazily loads a component or redirects', () => {
    for (const route of CONV_ROUTES) {
      const lazy =
        typeof route.loadComponent === 'function' ||
        typeof route.loadChildren === 'function' ||
        typeof route.redirectTo === 'string';
      expect(lazy).toBe(true);
    }
  });

  it('has no duplicate paths', () => {
    const paths = CONV_ROUTES.map(r => r.path);
    expect(new Set(paths).size).toBe(paths.length);
  });

  it('the operational route is "converse"', () => {
    const converseRoute = CONV_ROUTES.find(r => r.path === 'converse');
    expect(converseRoute).toBeDefined();
  });
});
